<script setup>
import { onMounted, reactive, ref } from 'vue'
import { api, paths, displayDate } from '../api'
const tab = ref('imports'), batches = ref([]), pending = ref([]), events = ref([]), report = ref(null), error = ref(''), message = ref(''), busy = ref(false)
const ingestion = reactive({ source_name: '', data_kind: 'demo', authorized_consent: false, csv_content: '' })
const opportunity = reactive({ source_record_id: '', title: '', organization: '', path: 'employment', organization_type: 'other', city: '衡阳', description: '', source_url: '', data_kind: 'public', requirements_verified: false, deadline: null, published_at: null, minimum_degree: null })
const skills = ref(''), majors = ref(''), note = ref('')
async function load() { try { [batches.value,pending.value,events.value] = await Promise.all([api('/admin/batches'), api('/admin/experiences'), api('/admin/audit')]) } catch(e) { error.value = e.message } }
async function readFile(e) {
  const file = e.target.files[0]; if(!file) return
  if(file.size > 500000) { error.value = 'CSV 文件请小于 500KB，每批最多2000行。'; return }
  ingestion.csv_content = await file.text(); error.value = ''
}
async function importCSV() {
  busy.value = true; error.value = ''; report.value = null
  try { report.value = await api('/admin/import/outcomes', { method: 'POST', body: ingestion }); await load() }
  catch(e) { error.value = e.message } finally { busy.value = false }
}
async function saveOpportunity() {
  busy.value = true; error.value = ''; message.value = ''
  try {
    const body = { ...opportunity, deadline: opportunity.deadline || null, published_at: opportunity.published_at || null, minimum_degree: opportunity.minimum_degree || null, skills: skills.value.split(/[,，、]/).map(x=>x.trim()).filter(Boolean), majors: majors.value.split(/[,，、]/).map(x=>x.trim()).filter(Boolean) }
    const result = await api('/admin/opportunities', { method: 'POST', body }); message.value = `机会已保存为 V${result.version}；相同来源链接与记录编号会创建新版本。`; await load()
  } catch(e) { error.value = e.message } finally { busy.value = false }
}
async function moderate(post,status) {
  try { await api(`/admin/experiences/${post.id}/moderate`, { method: 'POST', body: { status, note: note.value } }); await load() }
  catch(e) { error.value = e.message }
}
onMounted(load)
</script>
<template><div class="page-heading"><div><div class="eyebrow">DATA WORKSPACE</div><h1>让每一条数据有据可查<span class="heading-dot">.</span></h1><p>原始批次、清洗结果、版本记录与公开审核。</p></div><span class="tag">管理员</span></div><div v-if="error" class="alert error" role="alert">{{ error }}</div><div v-if="message" class="alert success">{{ message }}</div><div class="tabbar"><button v-for="[key,label] in [['imports','去向导入'],['opportunities','机会录入'],['moderation','经验审核'],['audit','操作记录']]" :key="key" :class="{active:tab === key}" @click="tab = key">{{ label }}</button></div><template v-if="tab === 'imports'"><form class="panel profile-form" @submit.prevent="importCSV"><h2>导入逐人去向 CSV</h2><p class="muted">使用 data/outcome-template.csv 表头，匿名标识应由数据授权方生成。不得加入姓名、学号、电话。不同来源分别统计，不直接相加。</p><div class="form-grid"><label>来源名称<input v-model="ingestion.source_name" required minlength="2" maxlength="120" placeholder="用明确名称区分样本批次来源"></label><label>数据类型<select v-model="ingestion.data_kind"><option value="demo">模拟数据</option><option value="authorized">真实授权样本</option></select></label></div><label>UTF-8 CSV 文件<input type="file" accept=".csv" @change="readFile" required></label><label v-if="ingestion.data_kind === 'authorized'" class="choice"><input type="checkbox" v-model="ingestion.authorized_consent" required>确认已取得授权、已使用随机匿名标识且不包含直接身份信息</label><button class="button" :disabled="busy || !ingestion.csv_content">{{ busy ? '导入中…' : '校验并导入' }}</button></form><section v-if="report" class="panel"><h2>本次质量报告 · 批次 #{{ report.batch_id }}</h2><div class="quality-grid"><div v-for="[key,label] in [['total','输入记录'],['accepted','接受'],['rejected','拒绝'],['duplicates','重复跳过']]" :key="key"><span>{{ label }}</span><strong>{{ report.quality[key] }}</strong></div></div><p>字段完整率 {{ (report.quality.completeness*100).toFixed(1) }}% · 校验通过率 {{ (report.quality.validation_pass_rate*100).toFixed(1) }}% · 重复率 {{ (report.quality.duplicate_rate*100).toFixed(1) }}%</p><p class="muted">解析正确率需人工抽样核对，当前未测量。规则版本：{{ report.quality.cleaning_version }}</p><p v-for="e in report.quality.errors" :key="e.line" class="error-text">第 {{ e.line }} 行：{{ e.reason }}</p></section><section class="panel table-panel"><h2>最近导入批次</h2><div class="table-scroll"><table><thead><tr><th>批次</th><th>来源</th><th>类型</th><th>接受 / 拒绝 / 重复</th><th>时间</th></tr></thead><tbody><tr v-for="b in batches" :key="b.id"><td>#{{ b.id }}</td><td>{{ b.source_name }}</td><td>{{ b.data_kind === 'demo' ? '模拟' : '授权' }}</td><td>{{ b.quality.accepted }} / {{ b.quality.rejected }} / {{ b.quality.duplicates }}</td><td>{{ displayDate(b.created_at) }}</td></tr></tbody></table></div><div v-if="!batches.length" class="empty">暂无导入批次</div></section></template><form v-if="tab === 'opportunities'" class="panel profile-form" @submit.prevent="saveOpportunity"><h2>录入已核对的机会资料</h2><div class="form-grid"><label>来源记录编号<input v-model="opportunity.source_record_id" required maxlength="80"></label><label>机会标题<input v-model="opportunity.title" required maxlength="150"></label><label>单位 / 院校<input v-model="opportunity.organization" required maxlength="150"></label><label>发展路径<select v-model="opportunity.path"><option v-for="p in ['employment','postgraduate','civil_service','public_institution','internship']" :key="p" :value="p">{{ paths[p] }}</option></select></label><label>单位性质<select v-model="opportunity.organization_type"><option value="other">其他 / 待核对</option><option value="private">民企</option><option value="state_owned">国企</option><option value="government">政府机关</option><option value="public_institution">事业单位</option><option value="university">高校</option></select></label><label>城市<input v-model="opportunity.city" maxlength="80"></label><label>截止日期<input type="date" v-model="opportunity.deadline"></label><label>发布日期<input type="date" v-model="opportunity.published_at"></label><label>最低学历<select v-model="opportunity.minimum_degree"><option :value="null">未知 / 需核对</option><option value="junior_college">专科</option><option value="bachelor">本科</option><option value="master">硕士</option><option value="doctor">博士</option></select></label><label>数据类型<select v-model="opportunity.data_kind"><option value="public">公开真实公告</option><option value="demo">模拟示例</option></select></label></div><label>技能要求（逗号或顿号分隔）<input v-model="skills"></label><label>结构化专业条件（须精确到标准名称；未知留空）<input v-model="majors"></label><label>原文 URL<input v-model="opportunity.source_url" type="url" required maxlength="255"></label><label>描述与资格说明<textarea v-model="opportunity.description" required rows="5" maxlength="10000"></textarea></label><label class="choice"><input v-model="opportunity.requirements_verified" type="checkbox">已人工核对结构化条件（复杂招考条件仍需用户核对原文）</label><button class="button" :disabled="busy">保存机会版本</button></form><section v-if="tab === 'moderation'" class="panel"><h2>待审核经验（{{ pending.length }}）</h2><label>审核说明<input v-model="note" maxlength="300" placeholder="注明依据或需修改之处"></label><div v-if="!pending.length" class="empty">暂无待审核经验</div><article v-for="p in pending" :key="p.id" class="moderation-card"><h3>{{ p.title }}</h3><p>{{ p.public_nickname }} · {{ p.graduation_year }} 届</p><p class="post-body">{{ p.body }}</p><div class="actions"><button class="button small" @click="moderate(p,'approved')">审核通过</button><button class="ghost" @click="moderate(p,'rejected')">拒绝发布</button></div></article></section><section v-if="tab === 'audit'" class="panel table-panel"><h2>最近操作记录</h2><div class="table-scroll"><table><thead><tr><th>编号</th><th>操作人 ID</th><th>操作</th><th>对象 ID</th><th>日期</th></tr></thead><tbody><tr v-for="e in events" :key="e.id"><td>{{ e.id }}</td><td>{{ e.actor_id }}</td><td>{{ e.action }}</td><td>{{ e.target_id }}</td><td>{{ displayDate(e.created_at) }}</td></tr></tbody></table></div></section></template>
